### **Question 25: Print payslip using structure and function**
```c
#include <stdio.h>

struct Employee {
    int id;
    char name[30];
    float basic_salary;
};

float calculateNetSalary(float basic) {
    float da = 0.10 * basic;
    float hra = 0.20 * basic;
    return basic + da + hra;
}

void printPayslip(struct Employee emp) {
    float netSalary = calculateNetSalary(emp.basic_salary);
    printf("\nPayslip:\n");
    printf("ID: %d\n", emp.id);
    printf("Name: %s\n", emp.name);
    printf("Basic Salary: %.2f\n", emp.basic_salary);
    printf("Net Salary: %.2f\n", netSalary);
}

int main() {
    struct Employee emp;
    printf("Enter Employee ID: ");
    scanf("%d", &emp.id);
    printf("Enter Name: ");
    scanf("%s", emp.name);
    printf("Enter Basic Salary: ");
    scanf("%f", &emp.basic_salary);

    printPayslip(emp);
    return 0;
}
```

