### **Question 27: Print payslip using call by value and call by reference**
```c
#include <stdio.h>

struct Employee {
    int id;
    char name[30];
    float basic_salary;
};

void getDetails(struct Employee *emp) {
    printf("Enter Employee ID: ");
    scanf("%d", &emp->id);
    printf("Enter Name: ");
    scanf("%s", emp->name);
    printf("Enter Basic Salary: ");
    scanf("%f", &emp->basic_salary);
}

void calculateNetSalary(struct Employee emp, float *netSalary) {
    *netSalary = emp.basic_salary + 0.10 * emp.basic_salary + 0.20 * emp.basic_salary;
}

void printPayslip(struct Employee emp, float netSalary) {
    printf("\nPayslip:\n");
    printf("ID: %d\n", emp.id);
    printf("Name: %s\n", emp.name);
    printf("Basic Salary: %.2f\n", emp.basic_salary);
    printf("Net Salary: %.2f\n", netSalary);
}

int main() {
    struct Employee emp;
    float netSalary;
    getDetails(&emp);
    calculateNetSalary(emp, &netSalary);  // Call by reference
    printPayslip(emp, netSalary);         // Call by value
    return 0;
}
```

