#include <stdio.h>

// Define the structure
struct Employee {
    int id;
    char name[30];
    float basic_salary;
};

// Function to calculate net salary
float calculateNetSalary(float basic) {
    float da = 0.10 * basic;
    float hra = 0.20 * basic;
    return basic + da + hra;
}

// Q25: Print payslip directly using values (structure + function)
void payslip_Q25() {
    struct Employee emp;
