// Q26: Use function to accept employee details
void getDetails(struct Employee *emp) {
    printf("\n[Q26] Enter Employee Details:\n");
    printf("ID: ");
    scanf("%d", &emp->id);
    printf("Name: ");
    scanf("%s", emp->name);
    printf("Basic Salary: ");
    scanf("%f", &emp->basic_salary);
}

void printPayslip_Q26(struct Employee emp) {
    float netSalary = calculateNetSalary(emp.basic_salary);

    printf("\nPayslip:\n");
    printf("ID: %d\n", emp.id);
    printf("Name: %s\n", emp.name);
    printf("Basic Salary: %.2f\n", emp.basic_salary);
    printf("Net Salary: %.2f\n", netSalary);
}

// Q27: Use call by value and call by reference
void calculateNetSalary_Q27(struct Employee emp, float *netSalary) {
    *netSalary = emp.basic_salary + 0.10 * emp.basic_salary + 0.20 * emp.basic_salary;
}

void printPayslip_Q27(struct Employee emp, float netSalary) {
    printf("\nPayslip:\n");
    printf("ID: %d\n", emp.id);
    printf("Name: %s\n", emp.name);
    printf("Basic Salary: %.2f\n", emp.basic_salary);
    printf("Net Salary: %.2f\n", netSalary);
}

int main() {
    int choice;
    struct Employee emp;
    float netSalary;

    do {
        printf("\n--- Employee Payslip Menu ---\n");
        printf("1. Q25: Print Payslip (Structure + Function)\n");
        printf("2. Q26: Accept Details using Function\n");
        printf("3. Q27: Call by Value & Reference\n");
        printf("0. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch(choice) {
            case 1:
                payslip_Q25();
                break;
            case 2:
                getDetails(&emp);
                printPayslip_Q26(emp);
                break;
            case 3:
                getDetails(&emp);
                calculateNetSalary_Q27(emp, &netSalary);
                printPayslip_Q27(emp, netSalary);
                break;
            case 0:
                printf("Exiting Program.\n");
                break;
            default:
                printf("Invalid choice! Try again.\n");
        }
    } while (choice != 0);

    return 0;
}
```

